//! Local browser QA input, generated by the real transcript path.
use mafold_transcript::{AgentEvent, RunStats, Transcript};
fn main() {
    let mut tx = Transcript::new();
    let mut stats = RunStats::codex(
        &serde_json::json!({"input_tokens":12000,"cached_input_tokens":8000,"output_tokens":2400}),
    );
    stats.model = Some("fixture-model".into());
    stats.provider = Some("Fixture provider".into());
    stats.effort = Some("high".into());
    stats.context_used_tokens = Some(8000);
    stats.context_limit_tokens = Some(32000);
    stats.context_basis = Some("last_request_input".into());
    stats.run_id = Some("fixture-run".into());
    stats.model_requests = Some(3);
    tx.push(&AgentEvent::Stats(stats));
    tx.push(&AgentEvent::Done {
        duration_ms: Some(12400.0),
        cost_usd: None,
        tokens: None,
    });
    print!("{}", tx.finish());
}
